contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amt) public payable {
        require(amt > 0);
        require(address(this).balance >= amt);
        c.deposit{value: amt}();
        uint256 beforeBalance = address(c).balance;
        c.refund();
        uint256 afterBalance = address(c).balance;
        // withdraw of 1 wei must now revert since balance was zeroed by refund
        bool reverted;
        try c.withdraw(1) { reverted = false; } catch { reverted = true; }
        assert(beforeBalance == amt && afterBalance == beforeBalance - amt && reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amt, uint256 wamt) public payable {
        require(amt > 0);
        require(address(this).balance >= amt);
        c.deposit{value: amt}();
        uint256 bal = c.balances(address(this));
        require(wamt > bal);
        bool reverted;
        try c.withdraw(wamt) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }

    receive() external payable {}
}
